    function ir(h) { var d = destino(h); lista.classList.remove('abierta'); if (d.split('#')[0] === location.href.split('#')[0]) { location.hash = ''; } location.href = d; }
    inp.addEventListener('input', pinta);
    inp.addEventListener('focus', pinta);
